import { describe, expect, it } from "vitest";
import { ENGAGEMENT_RANGE_TILES, WORLD_STEPS_PER_SECOND } from "../sailing.js";
import { claimRules, TREASURE_CIRCLE_RADIUS_TILES, validateClaimRules } from "./index.js";

function issuesOf(candidate: unknown): string[] {
  const result = validateClaimRules(candidate);
  return result.ok ? [] : result.issues;
}

describe("claim rules (§2, §5)", () => {
  it("channel for ten seconds and stop the match at minute 35, in world ticks", () => {
    expect(WORLD_STEPS_PER_SECOND).toBe(20);
    expect(claimRules.channelTicks).toBe(200);
    expect(claimRules.deadlineTicks).toBe(42_000);
    expect(claimRules.circleRadiusTiles).toBe(TREASURE_CIRCLE_RADIUS_TILES);
    expect(TREASURE_CIRCLE_RADIUS_TILES).toBeLessThan(ENGAGEMENT_RANGE_TILES);
    expect(validateClaimRules(claimRules)).toEqual({ ok: true, value: claimRules });
  });

  it("allow a zero-tick channel, §5's instant victory on arrival", () => {
    expect(issuesOf({ ...claimRules, channelTicks: 0 })).toEqual([]);
  });

  it("refuse fractional, negative or missing durations, a bad radius and unknown fields", () => {
    expect(issuesOf({ ...claimRules, channelTicks: 1.5 })[0]).toMatch(/^channelTicks:/);
    expect(issuesOf({ ...claimRules, channelTicks: -1 })[0]).toMatch(/^channelTicks:/);
    expect(issuesOf({ ...claimRules, deadlineTicks: 0 })[0]).toMatch(/^deadlineTicks:/);
    expect(issuesOf({ ...claimRules, circleRadiusTiles: 0 })[0]).toMatch(/^circleRadiusTiles:/);
    expect(issuesOf({ channelTicks: 200, deadlineTicks: 42_000 })[0]).toMatch(/^circleRadiusTiles:/);
    expect(issuesOf({ ...claimRules, extra: 1 })).toHaveLength(1);
  });

  it("refuse a channel that could never complete before the deadline", () => {
    expect(issuesOf({ ...claimRules, channelTicks: 42_000 })).toEqual([
      "channelTicks: a channel of 42000 ticks cannot complete before the deadline (42000 ticks)",
    ]);
  });
});
export * from "./rules.js";
import { z } from "zod";
import { formatIssues, type ValidationResult } from "../rules.js";
import { WORLD_STEPS_PER_SECOND } from "../sailing.js";

/** §5: a claim completes after holding interact this long. 0 would model §5's alternative, victory on arrival. */
export const CLAIM_CHANNEL_SECONDS = 10;
/** §2: the match stops 35 minutes after player control starts. */
export const MATCH_DURATION_MINUTES = 35;
/**
 * §5's treasure circle around the final island's claim point, centre to centre. A placeholder until playtests: wider
 * than a docking run (1.5 tiles), narrower than the engagement range (6 tiles), so a challenger can reach a claimer.
 */
export const TREASURE_CIRCLE_RADIUS_TILES = 4;

/** The claim rules (§2, §5) in world ticks (20 a second) and tiles; the simulation converts tiles to sub-units. */
export const claimRulesSchema = z
  .strictObject({
    /** World ticks of held interact that complete a claim; 0 completes it on the tick it starts. */
    channelTicks: z.int().nonnegative(),
    /** World ticks from player control to the match deadline. */
    deadlineTicks: z.int().positive(),
    circleRadiusTiles: z.int().positive(),
  })
  .superRefine((rules, ctx) => {
    if (rules.channelTicks >= rules.deadlineTicks) {
      ctx.addIssue({
        code: "custom",
        path: ["channelTicks"],
        message: `a channel of ${rules.channelTicks} ticks cannot complete before the deadline (${rules.deadlineTicks} ticks)`,
      });
    }
  });

export type ClaimRules = z.infer<typeof claimRulesSchema>;

export const claimRules: ClaimRules = {
  channelTicks: CLAIM_CHANNEL_SECONDS * WORLD_STEPS_PER_SECOND,
  deadlineTicks: MATCH_DURATION_MINUTES * 60 * WORLD_STEPS_PER_SECOND,
  circleRadiusTiles: TREASURE_CIRCLE_RADIUS_TILES,
};

export function validateClaimRules(candidate: unknown): ValidationResult<ClaimRules> {
  const parsed = claimRulesSchema.safeParse(candidate);
  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
}
import { z } from "zod";

/**
 * A rules preset (§18). The slice deliberately runs with fewer rubbing types, rubbings and islands than the alpha;
 * keeping the difference in data means slice shortcuts cannot silently ship into the main mode.
 */
export const rulesPresetSchema = z
  .strictObject({
    id: z.enum(["slice", "alpha"]),
    maxPlayers: z.int().min(1).max(8),
    rubbingTypes: z.int().positive(),
    rubbings: z.int().positive(),
    islands: z.int().positive(),
    sourcesPerIsland: z.int().positive(),
    fruitKits: z.int().positive(),
  })
  .superRefine((preset, ctx) => {
    if (preset.rubbings !== preset.islands * preset.sourcesPerIsland) {
      ctx.addIssue({
        code: "custom",
        path: ["rubbings"],
        message: `rubbings (${preset.rubbings}) must equal islands × sourcesPerIsland (${preset.islands * preset.sourcesPerIsland})`,
      });
    }
    if (preset.rubbings % preset.rubbingTypes !== 0) {
      ctx.addIssue({
        code: "custom",
        path: ["rubbingTypes"],
        message: `rubbings (${preset.rubbings}) must split evenly across ${preset.rubbingTypes} types`,
      });
    }
  });

export type RulesPreset = z.infer<typeof rulesPresetSchema>;
export type RulesPresetId = RulesPreset["id"];

export const rulesPresets = {
  /** Stage 2: four private players, four small islands with two sources each, two rubbing types, two fruits. */
  slice: { id: "slice", maxPlayers: 4, rubbingTypes: 2, rubbings: 8, islands: 4, sourcesPerIsland: 2, fruitKits: 2 },
  /** Stage 3: eight players, 12 islands with one source each, four rubbing types, six fruits. */
  alpha: { id: "alpha", maxPlayers: 8, rubbingTypes: 4, rubbings: 12, islands: 12, sourcesPerIsland: 1, fruitKits: 6 },
} as const satisfies Record<RulesPresetId, RulesPreset>;

export type ValidationResult<T> = { ok: true; value: T } | { ok: false; issues: string[] };

export function formatIssues(error: z.ZodError): string[] {
  return error.issues.map((issue) => `${issue.path.join(".") || "(root)"}: ${issue.message}`);
}

export function validateRulesPreset(candidate: unknown): ValidationResult<RulesPreset> {
  const parsed = rulesPresetSchema.safeParse(candidate);
  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
}

/** A private match (§2): custom, with a ship for every player as soon as they join. */
export interface PrivateMatchRules {
  readonly minPlayers: number;
  readonly maxPlayers: number;
  readonly custom: true;
}

export const privateMatch: PrivateMatchRules = {
  minPlayers: 1,
  maxPlayers: 8,
  custom: true,
};

