export * from "./state.js";
export * from "./step.js";
export {
  CLAIM_CHANNEL_SECONDS,
  claimRules,
  MATCH_DURATION_MINUTES,
  TREASURE_CIRCLE_RADIUS_TILES,
  validateClaimRules,
  type ClaimRules,
} from "@pirate-sea-race/content/claim";
export { hashState } from "../hash.js";
import { claimRules as defaultClaimRules, validateClaimRules, type ClaimRules } from "@pirate-sea-race/content/claim";
import { seaMap } from "@pirate-sea-race/content";

/** A point in integer sub-units. */
export interface ClaimPoint {
  readonly x: number;
  readonly y: number;
}

/** Static claim data for one match; the step reads it and it never changes. */
export interface ClaimConfig {
  /** The centre of the treasure circle on the final island. */
  readonly claimPoint: ClaimPoint;
  /** The treasure circle's radius in sub-units; a point exactly on it is inside. */
  readonly circleRadius: number;
  /** World ticks of held interact that complete a claim (0: the claim completes on the tick it starts). */
  readonly channelTicks: number;
  /** The world tick on which the match stops (§2). */
  readonly deadlineTick: number;
}

export interface ClaimConfigOptions {
  readonly claimPoint: ClaimPoint;
  /** The world tick on which player control starts; the deadline counts from it. */
  readonly controlStartTick?: number;
  readonly rules?: ClaimRules;
  readonly subUnitsPerTile?: number;
}

function requireInteger(value: number, name: string): void {
  if (!Number.isSafeInteger(value)) throw new RangeError(`${name} must be a safe integer, got ${value}`);
}

/** Builds a match's claim config from the content rules, refusing invalid rules. */
export function createClaimConfig(options: ClaimConfigOptions): ClaimConfig {
  const rules = validateClaimRules(options.rules ?? defaultClaimRules);
  if (!rules.ok) throw new RangeError(`invalid claim rules: ${rules.issues.join("; ")}`);
  const start = options.controlStartTick ?? 0;
  const subUnitsPerTile = options.subUnitsPerTile ?? seaMap.subUnitsPerTile;
  requireInteger(options.claimPoint.x, "claimPoint.x");
  requireInteger(options.claimPoint.y, "claimPoint.y");
  requireInteger(start, "controlStartTick");
  requireInteger(subUnitsPerTile, "subUnitsPerTile");
  if (start < 0) throw new RangeError(`controlStartTick must not be negative, got ${start}`);
  if (subUnitsPerTile <= 0) throw new RangeError(`subUnitsPerTile must be positive, got ${subUnitsPerTile}`);
  return {
    claimPoint: { x: options.claimPoint.x, y: options.claimPoint.y },
    circleRadius: rules.value.circleRadiusTiles * subUnitsPerTile,
    channelTicks: rules.value.channelTicks,
    deadlineTick: start + rules.value.deadlineTicks,
  };
}

/** The one active claim channel (§5). */
export interface ClaimChannel {
  readonly playerId: string;
  /** The tick the channel started on. */
  readonly startTick: number;
  /** Where the channeller stopped; any change of position is movement. */
  readonly x: number;
  readonly y: number;
  /** Ticks held since the start tick; the claim completes when this reaches `channelTicks`. */
  readonly progress: number;
}

export type ClaimResult =
  | { readonly reason: "claim"; readonly winner: string; readonly tick: number }
  | { readonly reason: "deadline"; readonly winner: null; readonly tick: number };

/** The claim state: plain integer data that `hashState` covers entirely. */
export interface ClaimState {
  /** The last world tick processed. */
  readonly tick: number;
  readonly channel: ClaimChannel | null;
  /** Set once, by a completed claim or the deadline; the state never changes afterwards. */
  readonly result: ClaimResult | null;
}

/** A state before any tick: the first step processes `tick + 1`. */
export function createClaimState(config: ClaimConfig, tick = 0): ClaimState {
  requireInteger(tick, "tick");
  if (tick >= config.deadlineTick) throw new RangeError(`the claim state must start before the deadline tick ${config.deadlineTick}`);
  return { tick, channel: null, result: null };
}

/** What the caller knows about one player on this tick. */
export interface ClaimPlayer {
  /** The stable player id; ties break on the lowest by UTF-16 code units. */
  readonly id: string;
  /** Position in sub-units. */
  readonly x: number;
  readonly y: number;
  /** Speed in sub-units per world tick; the player is stopped only at 0. */
  readonly speed: number;
  /** Holds all four rubbing types (from the ledger). */
  readonly holdsAllTypes: boolean;
  /** Holding interact on this tick. */
  readonly interact: boolean;
  readonly connected: boolean;
  /** Under spawn or return protection (§2, §6). Starting a claim ends it. */
  readonly protected: boolean;
}

/** An accepted encounter reservation: two players reserved for, or fighting, a duel (§6). */
export interface ClaimEncounter {
  readonly id: string;
  readonly playerIds: readonly [string, string];
}

/** One world tick's snapshot of the players that matter to the claim; order within the lists never matters. */
export interface ClaimTickInput {
  /** Must be the state's tick plus one. */
  readonly tick: number;
  /** A player absent from the list counts as disconnected. */
  readonly players: readonly ClaimPlayer[];
  /** Every encounter holding a reservation on this tick, newly accepted or still running. */
  readonly encounters: readonly ClaimEncounter[];
}

export type ClaimInterruptReason = "duel" | "disconnected" | "ineligible" | "moved" | "released" | "deadline";

/** Something that happened on a tick, for the caller to apply or announce. */
export type ClaimEvent =
  /** The channel reset to zero; `progress` is what was lost. */
  | { readonly kind: "claim-interrupted"; readonly tick: number; readonly playerId: string; readonly reason: ClaimInterruptReason; readonly progress: number }
  /** The player started a claim while protected: the caller must end their protection (§6). */
  | { readonly kind: "protection-ended"; readonly tick: number; readonly playerId: string }
  | { readonly kind: "claim-started"; readonly tick: number; readonly playerId: string }
  | { readonly kind: "claim-completed"; readonly tick: number; readonly playerId: string }
  /** The match ended with this encounter unresolved: the duel ends and no rubbing changes hands (§2). */
  | { readonly kind: "duel-ended-without-theft"; readonly tick: number; readonly encounterId: string; readonly playerIds: readonly [string, string] }
  /** The match is over; `winner` is null after a timeout (§2). */
  | { readonly kind: "match-ended"; readonly tick: number; readonly reason: "claim" | "deadline"; readonly winner: string | null };

export interface ClaimStepResult {
  readonly state: ClaimState;
  readonly events: readonly ClaimEvent[];
}
import { hashState } from "../hash.js";
import type {
  ClaimChannel,
  ClaimConfig,
  ClaimEncounter,
  ClaimEvent,
  ClaimInterruptReason,
  ClaimPlayer,
  ClaimResult,
  ClaimState,
  ClaimStepResult,
  ClaimTickInput,
} from "./state.js";

/** Squared distance from the claim point, refusing coordinates whose square would not be an exact integer. */
export function claimDistanceSquared(config: ClaimConfig, x: number, y: number): number {
  const dx = x - config.claimPoint.x;
  const dy = y - config.claimPoint.y;
  const squared = dx * dx + dy * dy;
  if (!Number.isSafeInteger(squared)) throw new RangeError(`position (${x}, ${y}) is too far from the claim point`);
  return squared;
}

export function insideTreasureCircle(config: ClaimConfig, x: number, y: number): boolean {
  return claimDistanceSquared(config, x, y) <= config.circleRadius * config.circleRadius;
}

/**
 * Whether a player meets §5's conditions to start claiming on this tick, protection aside: starting ends protection
 * (§6), so a protected player may start. A player can wait with interact held; this does not say a channel is free.
 */
export function canStartClaim(config: ClaimConfig, player: ClaimPlayer, reserved: boolean): boolean {
  return (
    player.connected &&
    player.holdsAllTypes &&
    player.interact &&
    !reserved &&
    player.speed === 0 &&
    insideTreasureCircle(config, player.x, player.y)
  );
}

/** Why the active channel cannot continue on this tick, or null. Reservations are checked before this. */
function channelBreak(channel: ClaimChannel, player: ClaimPlayer | undefined): ClaimInterruptReason | null {
  if (player === undefined || !player.connected) return "disconnected";
  if (!player.holdsAllTypes) return "ineligible";
  // The channel pins the position it started at, which lies inside the circle.
  if (player.speed !== 0 || player.x !== channel.x || player.y !== channel.y) return "moved";
  if (!player.interact) return "released";
  return null;
}

/** Lowest id by UTF-16 code units, independent of locale. */
function compareIds(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

function requireInteger(value: unknown, name: string): void {
  if (typeof value !== "number" || !Number.isSafeInteger(value)) throw new RangeError(`${name} must be a safe integer, got ${String(value)}`);
}

function requireBoolean(value: unknown, name: string): void {
  if (typeof value !== "boolean") throw new RangeError(`${name} must be a boolean, got ${String(value)}`);
}

function requireId(value: unknown, name: string): void {
  if (typeof value !== "string" || value.length === 0) throw new RangeError(`${name} must be a non-empty string`);
}

/** Refuses a malformed tick: a skipped or repeated tick, duplicate ids, a player in two encounters. */
function readInput(state: ClaimState, input: ClaimTickInput): { players: Map<string, ClaimPlayer>; reservedBy: Map<string, ClaimEncounter> } {
  requireInteger(input.tick, "tick");
  if (input.tick !== state.tick + 1) throw new RangeError(`expected tick ${state.tick + 1}, got ${input.tick}`);
  const players = new Map<string, ClaimPlayer>();
  for (const player of input.players) {
    requireId(player.id, "player id");
    if (players.has(player.id)) throw new RangeError(`player ${player.id} appears twice`);
    requireInteger(player.x, `${player.id}.x`);
    requireInteger(player.y, `${player.id}.y`);
    requireInteger(player.speed, `${player.id}.speed`);
    for (const flag of ["holdsAllTypes", "interact", "connected", "protected"] as const) requireBoolean(player[flag], `${player.id}.${flag}`);
    players.set(player.id, player);
  }
  const encounterIds = new Set<string>();
  const reservedBy = new Map<string, ClaimEncounter>();
  for (const encounter of input.encounters) {
    requireId(encounter.id, "encounter id");
    if (encounterIds.has(encounter.id)) throw new RangeError(`encounter ${encounter.id} appears twice`);
    encounterIds.add(encounter.id);
    const [a, b] = encounter.playerIds;
    requireId(a, `encounter ${encounter.id} player`);
    requireId(b, `encounter ${encounter.id} player`);
    if (a === b) throw new RangeError(`encounter ${encounter.id} reserves ${a} twice`);
    for (const id of [a, b]) {
      if (reservedBy.has(id)) throw new RangeError(`player ${id} is in two encounters`);
      reservedBy.set(id, encounter);
    }
  }
  return { players, reservedBy };
}

/**
 * One world tick of §5's claim rules, in a fixed order: (1) accepted encounter reservations interrupt the channel,
 * (2) the active channel breaks or advances, (3) with no channel active the best eligible starter begins one,
 * (4) a channel that has run `channelTicks` completes, and (5) on the deadline tick a match without a winner ends with
 * none. Players and encounters are read as sets, so their order in the input never matters. Once the match has a
 * result, every later input is ignored and the state is returned unchanged. The input state is never mutated.
 */
export function stepClaim(config: ClaimConfig, state: ClaimState, input: ClaimTickInput): ClaimStepResult {
  if (state.result !== null) return { state, events: [] };
  const { players, reservedBy } = readInput(state, input);
  const tick = input.tick;
  const events: ClaimEvent[] = [];
  let channel = state.channel;
  const interrupt = (active: ClaimChannel, reason: ClaimInterruptReason) =>
    events.push({ kind: "claim-interrupted", tick, playerId: active.playerId, reason, progress: active.progress });

  // 1. Reservations first (§5): a duel accepted on the tick a claim would complete still stops it.
  if (channel !== null && reservedBy.has(channel.playerId)) {
    interrupt(channel, "duel");
    channel = null;
  }

  // 2. The active channel.
  if (channel !== null) {
    const reason = channelBreak(channel, players.get(channel.playerId));
    if (reason === null) {
      channel = { ...channel, progress: channel.progress + 1 };
    } else {
      interrupt(channel, reason);
      channel = null;
    }
  }

  // 3. One channel at a time: others wait. Simultaneous starters: the closest to the claim point, then the lowest id.
  if (channel === null) {
    let best: { player: ClaimPlayer; distance: number } | null = null;
    for (const player of players.values()) {
      if (!canStartClaim(config, player, reservedBy.has(player.id))) continue;
      const distance = claimDistanceSquared(config, player.x, player.y);
      if (best === null || distance < best.distance || (distance === best.distance && compareIds(player.id, best.player.id) < 0)) {
        best = { player, distance };
      }
    }
    if (best !== null) {
      const { id, x, y } = best.player;
      if (best.player.protected) events.push({ kind: "protection-ended", tick, playerId: id });
      events.push({ kind: "claim-started", tick, playerId: id });
      channel = { playerId: id, startTick: tick, x, y, progress: 0 };
    }
  }

  // 4. Completion commits the winner; it comes before the deadline, so a claim completing on the deadline tick wins.
  let result: ClaimResult | null = null;
  if (channel !== null && channel.progress >= config.channelTicks) {
    events.push({ kind: "claim-completed", tick, playerId: channel.playerId });
    result = { reason: "claim", winner: channel.playerId, tick };
    channel = null;
  }

  // 5. The deadline: no winner, and an unfinished channel is cancelled.
  if (result === null && tick >= config.deadlineTick) {
    if (channel !== null) interrupt(channel, "deadline");
    channel = null;
    result = { reason: "deadline", winner: null, tick };
  }

  // The match is over: outcomes freeze, so every duel still reserved or running ends without theft.
  if (result !== null) {
    const encounters = [...input.encounters].sort((a, b) => compareIds(a.id, b.id));
    for (const encounter of encounters) {
      // In id order, so the event never echoes the order the caller listed the players in.
      const playerIds = [...encounter.playerIds].sort(compareIds) as [string, string];
      events.push({ kind: "duel-ended-without-theft", tick, encounterId: encounter.id, playerIds });
    }
    events.push({ kind: "match-ended", tick, reason: result.reason, winner: result.winner });
  }

  return { state: { tick, channel, result }, events };
}

export interface ClaimReplay {
  readonly state: ClaimState;
  readonly events: readonly ClaimEvent[];
  readonly hash: string;
}

/** Steps a sequence of ticks from a state, collecting every event; `hash` is the final state's `hashState`. */
export function replayClaim(config: ClaimConfig, state: ClaimState, inputs: readonly ClaimTickInput[]): ClaimReplay {
  let current = state;
  const events: ClaimEvent[] = [];
  for (const input of inputs) {
    const stepped = stepClaim(config, current, input);
    current = stepped.state;
    events.push(...stepped.events);
  }
  return { state: current, events, hash: hashState(current) };
}
import { z } from "zod";
import { formatIssues, type ValidationResult } from "../rules.js";
import { WORLD_STEPS_PER_SECOND } from "../sailing.js";

/** The sea is split into a grid of named sectors this many columns wide and rows high (§2's "sectors"). */
export const SECTOR_COLUMNS = 3;
export const SECTOR_ROWS = 3;

/** The nine sector names, row by row from the north-west corner. */
export const SECTOR_NAMES = [
  "North-West Reach",
  "Northern Waters",
  "North-East Reach",
  "Western Waters",
  "Central Waters",
  "Eastern Waters",
  "South-West Reach",
  "Southern Waters",
  "South-East Reach",
] as const;

/**
 * §11: a carrier sighting is coarse and delayed. It reads the carrier snapshot taken one interval before the latest,
 * so it is at least this old (and less than twice this old), never the current location.
 */
export const CARRIER_SIGHTING_DELAY_SECONDS = 30;
/** §2: from minute 28 the carriers' sectors are published every 30 seconds; the carrier snapshots keep the same beat. */
export const CARRIER_INTERVAL_SECONDS = 30;
/** §2: at minute 20 the sectors holding unclaimed rubbings and abandoned caches are revealed. */
export const SECTOR_REVEAL_MINUTE = 20;
/** §2: from minute 28 the carriers' approximate sectors are published. */
export const CARRIER_REVEAL_MINUTE = 28;
/** §11: what the caller charges for a targeted rumor that delivers something. */
export const TARGETED_RUMOR_GOLD = 25;

/** The information rules (§2, §3, §11) in world ticks (20 a second), counted from the start of player control. */
export const intelRulesSchema = z
  .strictObject({
    sectorColumns: z.int().positive(),
    sectorRows: z.int().positive(),
    /** Row by row from the north-west; one unique, non-empty name per sector. */
    sectorNames: z.array(z.string().min(1)),
    /** How old a carrier sighting is at least; it must equal the carrier interval, since sightings read the previous snapshot. */
    sightingDelayTicks: z.int().positive(),
    /** The beat of the carrier snapshots, of the sighting cap and, from the carrier reveal on, of the carrier broadcasts. */
    carrierIntervalTicks: z.int().positive(),
    /** Ticks from control start to the reveal of the sectors holding unclaimed rubbings and caches. */
    sectorRevealTicks: z.int().positive(),
    /** Ticks from control start to the first carrier broadcast: a multiple of the carrier interval, so it falls on a snapshot boundary. */
    carrierRevealTicks: z.int().positive(),
    targetedRumorGold: z.int().nonnegative(),
  })
  .superRefine((rules, ctx) => {
    if (rules.sectorNames.length !== rules.sectorColumns * rules.sectorRows) {
      ctx.addIssue({
        code: "custom",
        path: ["sectorNames"],
        message: `${rules.sectorNames.length} names for a ${rules.sectorColumns} × ${rules.sectorRows} grid`,
      });
    }
    if (new Set(rules.sectorNames).size !== rules.sectorNames.length) {
      ctx.addIssue({ code: "custom", path: ["sectorNames"], message: "sector names must be unique" });
    }
    if (rules.sightingDelayTicks !== rules.carrierIntervalTicks) {
      ctx.addIssue({
        code: "custom",
        path: ["sightingDelayTicks"],
        message: `the sighting delay (${rules.sightingDelayTicks} ticks) must equal the carrier interval (${rules.carrierIntervalTicks} ticks)`,
      });
    }
    if (rules.sectorRevealTicks >= rules.carrierRevealTicks) {
      ctx.addIssue({
        code: "custom",
        path: ["carrierRevealTicks"],
        message: `the carrier reveal (${rules.carrierRevealTicks} ticks) must come after the sector reveal (${rules.sectorRevealTicks} ticks)`,
      });
    }
    // The broadcasts must fall on snapshot boundaries, so a pending sighting and a new one never split across messages.
    if (rules.carrierIntervalTicks > 0 && rules.carrierRevealTicks % rules.carrierIntervalTicks !== 0) {
      ctx.addIssue({
        code: "custom",
        path: ["carrierRevealTicks"],
        message: `the carrier reveal (${rules.carrierRevealTicks} ticks) must be a multiple of the carrier interval (${rules.carrierIntervalTicks} ticks)`,
      });
    }
  });

export type IntelRules = z.infer<typeof intelRulesSchema>;

export const intelRules: IntelRules = {
  sectorColumns: SECTOR_COLUMNS,
  sectorRows: SECTOR_ROWS,
  sectorNames: [...SECTOR_NAMES],
  sightingDelayTicks: CARRIER_SIGHTING_DELAY_SECONDS * WORLD_STEPS_PER_SECOND,
  carrierIntervalTicks: CARRIER_INTERVAL_SECONDS * WORLD_STEPS_PER_SECOND,
  sectorRevealTicks: SECTOR_REVEAL_MINUTE * 60 * WORLD_STEPS_PER_SECOND,
  carrierRevealTicks: CARRIER_REVEAL_MINUTE * 60 * WORLD_STEPS_PER_SECOND,
  targetedRumorGold: TARGETED_RUMOR_GOLD,
};

export function validateIntelRules(candidate: unknown): ValidationResult<IntelRules> {
  const parsed = intelRulesSchema.safeParse(candidate);
  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
}
import { describe, expect, it } from "vitest";
import { WORLD_STEPS_PER_SECOND } from "../sailing.js";
import {
  CARRIER_INTERVAL_SECONDS,
  CARRIER_REVEAL_MINUTE,
  CARRIER_SIGHTING_DELAY_SECONDS,
  intelRules,
  SECTOR_COLUMNS,
  SECTOR_NAMES,
  SECTOR_REVEAL_MINUTE,
  SECTOR_ROWS,
  TARGETED_RUMOR_GOLD,
  validateIntelRules,
} from "./index.js";

function issuesOf(candidate: unknown): string[] {
  const result = validateIntelRules(candidate);
  return result.ok ? [] : result.issues;
}

describe("intel rules (§2, §3, §11)", () => {
  it("use a 3 × 3 grid of unique names, a 30 s delay and interval, and reveals at minutes 20 and 28, in world ticks", () => {
    expect(WORLD_STEPS_PER_SECOND).toBe(20);
    expect([SECTOR_COLUMNS, SECTOR_ROWS]).toEqual([3, 3]);
    expect(SECTOR_NAMES).toHaveLength(9);
    expect(new Set(SECTOR_NAMES).size).toBe(9);
    expect([CARRIER_SIGHTING_DELAY_SECONDS, CARRIER_INTERVAL_SECONDS, SECTOR_REVEAL_MINUTE, CARRIER_REVEAL_MINUTE]).toEqual([30, 30, 20, 28]);
    expect(TARGETED_RUMOR_GOLD).toBe(25);
    expect(intelRules).toMatchObject({
      sightingDelayTicks: 600,
      carrierIntervalTicks: 600,
      sectorRevealTicks: 24_000,
      carrierRevealTicks: 33_600,
      targetedRumorGold: 25,
    });
    expect(validateIntelRules(intelRules)).toEqual({ ok: true, value: intelRules });
  });

  it("refuse a carrier interval of 0 and reveal times out of order", () => {
    expect(issuesOf({ ...intelRules, carrierIntervalTicks: 0, sightingDelayTicks: 0 }).some((issue) => issue.startsWith("carrierIntervalTicks:"))).toBe(true);
    expect(issuesOf({ ...intelRules, sectorRevealTicks: 33_600 })).toEqual([
      "carrierRevealTicks: the carrier reveal (33600 ticks) must come after the sector reveal (33600 ticks)",
    ]);
    expect(issuesOf({ ...intelRules, sectorRevealTicks: 40_000 })).toHaveLength(1);
  });

  it("refuse a carrier reveal that is not a multiple of the carrier interval", () => {
    expect(issuesOf({ ...intelRules, carrierRevealTicks: 33_601 })).toEqual([
      "carrierRevealTicks: the carrier reveal (33601 ticks) must be a multiple of the carrier interval (600 ticks)",
