/**
 * A seeded match seen from outside: ships sail and turn, players collect sealed sources and claim caches, fight duels
 * (reserving their rubbings) that end in a theft or a draw, leave (their rubbings go into a cache where they were)
 * and join, and buy targeted rumors, sometimes repeating a request id. Some scenarios jump several ticks at once.
 */
function randomScript(scenario: Scenario, config: IntelConfig, map: IntelMapShape): IntelReplayTick[] {
  const draw = generator(scenario.seed);
  const chance = (perMille: number) => draw(1000) < perMille;
  const preset = rulesPresets[scenario.preset];
  const width = map.widthTiles * T;
  const height = map.heightTiles * T;
  const players = new Map<string, SimPlayer>();
  let nextPlayer = 0;
  const join = () => {
    players.set(`crew-${nextPlayer++}`, { x: draw(width), y: draw(height), heading: draw(8) });
  };
  for (let index = 0; index < preset.maxPlayers; index++) join();
  const rubbings = new Map<string, IntelRubbing>();
  const deck = presetRubbings(preset);
  deck.forEach((rubbing, index) => {
    const island = Math.floor(index / preset.sourcesPerIsland);
    // Spread each type over the islands: deal by a seeded shuffle of the deck positions.
    rubbings.set(rubbing.id, { id: rubbing.id, type: rubbing.type, place: { kind: "source", island, ...islandPoint(map, island) } });
  });
  // Shuffle which type sits on which island.
  const ids = [...rubbings.keys()];
  for (let index = ids.length - 1; index > 0; index--) {
    const other = draw(index + 1);
    const a = rubbings.get(ids[index]!)!;
    const b = rubbings.get(ids[other]!)!;
    rubbings.set(a.id, { ...a, place: b.place });
    rubbings.set(b.id, { ...b, place: a.place });
  }

